import Foundation

// DevkitBridge.swift — the GUI ↔ core contract (M7). Owned by the integrator;
// feature agents do not edit this file, they report gaps instead.
//
// Sources of truth (drift-check against these):
//   - DTO field shapes:  src/steamos_devkit/models.py (pydantic, snake_case JSON)
//   - Tool names/args:   src/steamos_devkit/mcp_server.py (spec section 11)
//   - Error codes:       src/steamos_devkit/errors.py (ErrorCode)
//
// Wire facts the implementation relies on (verified empirically against the
// real server, mcp SDK 2.3.0, during the M7 bridge bring-up):
//   - Transport is MCP stdio: newline-delimited JSON-RPC 2.0, UTF-8. The
//     initialize handshake negotiates protocolVersion "2025-06-18".
//   - Successful tool results always carry `structuredContent` (collection
//     results wrapped as {"result": [...]}); decode prefers it.
//   - Tool errors come back as `isError: true` results whose first text content
//     is the JSON payload {"code", "message", "details"?, "remote_exit_code"?}
//     PREFIXED with "Error executing tool <name>: " (SDK behavior) — parse from
//     the first '{'.
//   - `resources/read` failures are JSON-RPC error responses (-32602), not
//     isError results.
//   - Job-starting tools return {"job_id", "status": "queued"} immediately.
//     When the call carries `_meta.progressToken`, the server bridges journal
//     progress to connection-level `notifications/progress` (params:
//     {progressToken, progress, total?, message?}) until the job is terminal.
//     Notifications for a token may arrive BEFORE that call's response.
//   - Artifact bytes are read via `resources/read` on `devkit://artifact/<id>`:
//     base64 `blob` for binary kinds, `text` (bounded excerpt) for text kinds.

// MARK: - JSON plumbing

/// JSON value for open-ended payloads (`DeviceStatus.raw`, error `details`).
enum JSONValue: Codable, Equatable, Sendable, CustomStringConvertible {
    case string(String)
    case int(Int)
    case double(Double)
    case bool(Bool)
    case null
    case array([JSONValue])
    case object([String: JSONValue])

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null } else if let v = try? c.decode(Bool.self) {
            self = .bool(v)
        } else if let v = try? c.decode(Int.self) { self = .int(v) } else if let v = try? c.decode(Double.self) {
            self = .double(v)
        } else if let v = try? c.decode(String.self) { self = .string(v) } else if let v = try? c.decode([JSONValue].self) {
            self = .array(v)
        } else { self = .object(try c.decode([String: JSONValue].self)) }
    }

    func encode(to encoder: Encoder) throws {
        var c = encoder.singleValueContainer()
        switch self {
        case .string(let v): try c.encode(v)
        case .int(let v): try c.encode(v)
        case .double(let v): try c.encode(v)
        case .bool(let v): try c.encode(v)
        case .null: try c.encodeNil()
        case .array(let v): try c.encode(v)
        case .object(let v): try c.encode(v)
        }
    }

    var description: String {
        switch self {
        case .string(let v): return v
        case .int(let v): return String(v)
        case .double(let v): return String(v)
        case .bool(let v): return String(v)
        case .null: return "null"
        case .array(let v): return v.description
        case .object(let v): return v.description
        }
    }
}

/// Codable helpers. `DeviceStatus.steamOsclientVersion` is `int | str | null`
/// on the wire, hence JSONValue there; everything else uses concrete types.
/// `pythonPath`/`Path` fields are plain strings; timestamps are ISO-8601 UTC
/// with optional fractional seconds (pydantic `mode="json"`).
enum DevkitJSON {
    static func makeDecoder() -> JSONDecoder {
        let d = JSONDecoder()
        d.keyDecodingStrategy = .convertFromSnakeCase
        d.dateDecodingStrategy = .custom { decoder in
            let container = try decoder.singleValueContainer()
            let text = try container.decode(String.self)
            if let date = ISODate.parse(text) { return date }
            throw DecodingError.dataCorruptedError(
                in: container, debugDescription: "not an ISO-8601 timestamp: \(text)")
        }
        return d
    }

    static func makeEncoder() -> JSONEncoder {
        let e = JSONEncoder()
        e.keyEncodingStrategy = .convertToSnakeCase
        return e
    }
}

enum ISODate {
    static func parse(_ text: String) -> Date? {
        let withFractional = ISO8601DateFormatter()
        withFractional.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        if let date = withFractional.date(from: text) { return date }
        let plain = ISO8601DateFormatter()
        plain.formatOptions = [.withInternetDateTime]
        return plain.date(from: text)
    }

    static func string(_ date: Date) -> String {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return f.string(from: date)
    }
}

// MARK: - Error model (errors.py)

/// Stable wire codes; keep in sync with errors.py `ErrorCode`.
enum ErrorCodes {
    static let deviceNotFound = "DEVICE_NOT_FOUND"
    static let deviceUnreachable = "DEVICE_UNREACHABLE"
    static let ambiguousDevice = "AMBIGUOUS_DEVICE"
    static let pairingDeclined = "PAIRING_DECLINED"
    static let pairingTimeout = "PAIRING_TIMEOUT"
    static let pairingFailed = "PAIRING_FAILED"
    static let dependencyMissing = "DEPENDENCY_MISSING"
    static let openrsyncDetected = "OPENRSYNC_DETECTED"
    static let permissionLocalNetwork = "PERMISSION_LOCAL_NETWORK"
    static let permissionKeyFile = "PERMISSION_KEY_FILE"
    static let validation = "VALIDATION"
    static let unsupported = "UNSUPPORTED"
    static let remoteCommandFailed = "REMOTE_COMMAND_FAILED"
    static let timeout = "TIMEOUT"
    static let cancelled = "CANCELLED"
    static let jobNotFound = "JOB_NOT_FOUND"
    static let artifactNotFound = "ARTIFACT_NOT_FOUND"
    static let stateCorrupt = "STATE_CORRUPT"
    static let internalError = "INTERNAL"
}

/// The structured payload inside an `isError` tool result.
struct DevkitErrorPayload: Codable, Equatable, Sendable {
    var code: String
    var message: String
    var details: [String: JSONValue]?
    var remoteExitCode: Int?
}

enum BridgeError: Error, Equatable, Sendable {
    /// A DevkitError surfaced by a tool (`isError` result).
    case devkit(DevkitErrorPayload)
    /// A JSON-RPC protocol error response (bad method, parse error, ...).
    case rpc(code: Int, message: String)
    /// Spawn failure, broken pipe, server exit mid-call.
    case transport(String)
    /// A response did not decode into the expected type.
    case decoding(String)
    /// Handshake or framing violation.
    case protocolViolation(String)
}

