// MARK: - Titles and deploys

enum CompatToolAlias: String, Codable, Equatable, Sendable, CaseIterable {
    case protonStable = "proton-stable"
    case protonExperimental = "proton-experimental"
    case scout = "SteamLinuxRuntime"
    case sniper = "SteamLinuxRuntime_sniper"
    case lepton = "lepton"
    case arm64 = "SteamLinuxRuntime_4-arm64"
    case x86_64 = "SteamLinuxRuntime_4"
}

struct Title: Codable, Equatable, Sendable {
    var gameid: String
    /// nil: registration is not knowable from the device helpers.
    var registeredWithSteam: Bool?
    var sizeBytes: Int?
    var modified: Date?
}

/// Launch configuration. In write contexts (configure/deploy) nil entrypoint
/// and empty collections mean "leave unchanged" — the server merges per the
/// H1-fixed semantics (spec appendix A, external-review fixes).
struct TitleConfig: Codable, Equatable, Sendable {
    var entrypoint: String?
    var args: [String]
    var env: [String: String]
    var runtime: CompatToolAlias?
    var settings: [String: String]

    init(
        entrypoint: String? = nil, args: [String] = [], env: [String: String] = [:],
        runtime: CompatToolAlias? = nil, settings: [String: String] = [:]
    ) {
        self.entrypoint = entrypoint
        self.args = args
        self.env = env
        self.runtime = runtime
        self.settings = settings
    }
}

struct TitleDetail: Codable, Equatable, Sendable {
    var gameid: String
    var registeredWithSteam: Bool?
    var sizeBytes: Int?
    var modified: Date?
    var config: TitleConfig
    var remoteDir: String?
}

enum FilterMode: String, Codable, Equatable, Sendable {
    case exclude
    case include
    case raw
}

struct FilterSpec: Codable, Equatable, Sendable {
    var mode: FilterMode
    var patterns: [String]

    init(mode: FilterMode = .exclude, patterns: [String] = []) {
        self.mode = mode
        self.patterns = patterns
    }
}

/// `checksum` and `update` are mutually exclusive (server validates).
struct DeploySpec: Codable, Equatable, Sendable {
    var device: String
    var gameid: String
    var sourceDir: String
    var filters: FilterSpec
    var clean: Bool
    var checksum: Bool
    var update: Bool
    var compress: Bool
    var register: Bool
    var launch: Bool
    var config: TitleConfig?

    init(
        device: String, gameid: String, sourceDir: String,
        filters: FilterSpec = FilterSpec(), clean: Bool = false, checksum: Bool = false,
        update: Bool = false, compress: Bool = true, register: Bool = true,
        launch: Bool = false, config: TitleConfig? = nil
    ) {
        self.device = device
        self.gameid = gameid
        self.sourceDir = sourceDir
        self.filters = filters
        self.clean = clean
        self.checksum = checksum
        self.update = update
        self.compress = compress
        self.register = register
        self.launch = launch
        self.config = config
    }
}

struct DeployPreview: Codable, Equatable, Sendable {
    var filesAdded: Int
    var filesChanged: Int
    var filesDeleted: Int
    var bytesToTransfer: Int
    var sampleChanges: [String]
    var warnings: [String]
}

struct LaunchResult: Codable, Equatable, Sendable {
    var gameid: String
    var launched: Bool
    var deviceResponse: String
    /// Always "unknown": upstream has no readiness signal.
    var readiness: String
}

// MARK: - Result envelope

/// models.py `Result`; renamed to avoid clashing with `Swift.Result`.
struct DevkitResult: Codable, Equatable, Sendable {
    var ok: Bool
    var code: String?
    var device: Device?
    var message: String?
    var uploadComplete: Bool?
    var registrationComplete: Bool?
