}

// MARK: - Jobs (models.py + mcp_server.py JobStarted)

enum JobKind: String, Codable, Equatable, Sendable {
    case deploy
    case fetchLogs = "fetch_logs"
    case screenshot
    case controllerConfig = "controller_config"
    case gpuTrace = "gpu_trace"
    case rgp
}

enum JobState: String, Codable, Equatable, Sendable {
    case queued
    case running
    case succeeded
    case failed
    case cancelled
    case interrupted
    case timeout

    var isTerminal: Bool {
        switch self {
        case .succeeded, .failed, .cancelled, .interrupted, .timeout: return true
        case .queued, .running: return false
        }
    }
}

struct JobProgress: Codable, Equatable, Sendable {
    var phase: String
    var bytesDone: Int?
    var bytesTotal: Int?
    var itemsDone: Int?
    var rateBps: Double?
}

struct JobInfo: Codable, Equatable, Sendable, Identifiable {
    var id: String
    var kind: JobKind
    var state: JobState
    var device: String?
    var gameid: String?
    var createdAt: Date
    var startedAt: Date?
    var finishedAt: Date?
    var timeoutS: Int?
    var progress: JobProgress?
    var code: String?
    var message: String?
    var artifacts: [String]
}

/// Immediate answer of job-starting tools plus the client-generated token
/// whose `notifications/progress` events belong to this job.
struct JobStart: Equatable, Sendable {
    var jobId: String
    var progressToken: String
}

/// One connection-level `notifications/progress` event.
struct ProgressNotification: Equatable, Sendable {
    var progressToken: String
    var progress: Double
    var total: Double?
    var message: String?
}

// MARK: - Artifacts

enum ArtifactKind: String, Codable, Equatable, Sendable {
    case logs
    case protonLog = "proton_log"
    case screenshot
    case controllerConfig = "controller_config"
    case gpuTrace = "gpu_trace"
    case rgp
    case frametimes
    case dumps
}

struct Artifact: Codable, Equatable, Sendable, Identifiable {
    var id: String
    var jobId: String
    var device: String
    var kind: ArtifactKind
    var path: String
    var bytes: Int
    var sha256: String
    var mediaType: String?
    var remoteSource: String
    var createdAt: Date
}

struct ArtifactEntry: Codable, Equatable, Sendable, Identifiable {
    var artifact: Artifact
    var resourceUri: String

    var id: String { artifact.id }
}

struct ArtifactRead: Codable, Equatable, Sendable {
    var artifactId: String
    var kind: String
    var mediaType: String?
    var resourceUri: String
    /// Bounded tail for text artifacts; nil for binary/directory artifacts.
    var excerpt: String?
}

/// Payload of `resources/read` on `devkit://artifact/<id>` (binary kinds).
struct ArtifactPayload: Equatable, Sendable {
    var data: Data
    var mimeType: String
}

